"""Second study: whole-character creatures, drawn independently from reference.
Coordinates use a 1000-unit square, y downward. Edit this file, not exported JSON.
"""
import math
WIDTH = 28

def line(*pts, w=WIDTH): return {'points': pts, 'width': w}
def q(a,b,c,n=22):
    return [((1-t)**2*a[0]+2*(1-t)*t*b[0]+t*t*c[0], (1-t)**2*a[1]+2*(1-t)*t*b[1]+t*t*c[1]) for t in [i/n for i in range(n+1)]]
def curve(a,b,c,w=WIDTH): return line(*q(a,b,c),w=w)
def path(start,*segments,w=WIDTH):
    pts=[start]
    for seg in segments:
        if len(seg)==2: pts+=q(pts[-1],*seg)[1:]
        else: pts.append(seg[0])
    return line(*pts,w=w)
def bean(cx,cy,rx,ry,tilt=0,w=WIDTH):
    # Non-elliptical outline: a shallow crown, uneven cheeks and a broad chin.
    pts=[]
    for i in range(81):
        t=2*math.pi*i/80
        x=rx*math.cos(t)*(1+.065*math.sin(3*t))
        y=ry*math.sin(t)*(1+.09*math.cos(t))
        pts.append((cx+x*math.cos(tilt)-y*math.sin(tilt),cy+x*math.sin(tilt)+y*math.cos(tilt)))
    return line(*pts,w=w)
def oval(cx,cy,rx,ry): return bean(cx,cy,rx,ry)
def box(x,y,w,h): return bean(x+w/2,y+h/2,w/2,h/2)
def glance(x,y,gap=67):
    return [curve((x-gap/2-5,y-21),(x-gap/2+6,y),(x-gap/2+1,y+24),w=23),curve((x+gap/2,y-25),(x+gap/2+10,y-1),(x+gap/2+7,y+18),w=23)]
def shift(parts,x,y,sx=1,sy=None):
    sy=sx if sy is None else sy
    return [{'points':[(x+u*sx,y+v*sy) for u,v in p['points']], 'width':p['width']} for p in parts]

